{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_master_summary_tbl AS With sales_summary AS ( SELECT h.SKU_GROUP, c.COLLECTION AS CAPSULE, ANY_VALUE(h.CATEGORY) AS CATEGORY, SUM(h.GROSS_QUANTITY) AS TOTAL_QTY, SUM(h.GROSS_SALES) AS GROSS_SALES, SUM(h.DISCOUNT_AMOUNT) AS TOTAL_DISCOUNT, ROUND( SUM(h.GROSS_SALES) / NULLIF(SUM(h.GROSS_QUANTITY),0), 2 ) AS ASP_GROSS FROM snitch_db.maplemonk.horizontal_sales_categories h JOIN ( ( SELECT DISTINCT SKU, COLLECTION FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 UNION ALL SELECT DISTINCT skugroup as sku, CASE WHEN skugroup like \'%4MSFR%\' then \'PERFUMES\' else \'SHOES\' end as collection FROM snitch_db.maplemonk.uc_final_item_master where sku like \'%4MSFR%\' or sku like \'SH%\' ) ) c ON h.SKU_GROUP = c.SKU GROUP BY h.SKU_GROUP, c.COLLECTION ), images AS ( SELECT SKU_GROUP, IMAGE_URL FROM ( SELECT LEFT( variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING)) ) AS SKU_GROUP, image.value:\"preview\":\"image\":\"url\"::STRING AS IMAGE_URL, ROW_NUMBER() OVER ( PARTITION BY LEFT( variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING)) ) ORDER BY image.index, t.id ) AS RN FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => PARSE_JSON(t.media)) image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) variant WHERE image.value:\"mediaContentType\"::STRING = \'IMAGE\' ) WHERE RN = 1 ), inventory AS ( SELECT i.SKU_GROUP, i.QTY_AVAILABLE AS WH_INVENTORY, i.QTY_OFFLINE_AVAILABLE AS STORE_INVENTORY FROM snitch_db.maplemonk.cogs_daily_snapshot i JOIN ( ( SELECT DISTINCT SKU, COLLECTION FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 UNION ALL SELECT DISTINCT skugroup as sku, CASE WHEN skugroup like \'%4MSFR%\' then \'PERFUMES\' else \'SHOES\' end as collection FROM snitch_db.maplemonk.uc_final_item_master where sku like \'%4MSFR%\' or sku like \'SH%\' ) ) c ON i.SKU_GROUP = c.SKU WHERE i.DATE=( SELECT MAX(DATE) FROM snitch_db.maplemonk.cogs_daily_snapshot )), putaway_base AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\',REVERSE(\"Item Type skuCode\"))+1, LEN(\"Item Type skuCode\") )))) AS SKU_GROUP, \"PUTAWAY_UPDATED\"::DATE AS INWARD_DATE, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS INWARD_QTY FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2 ), inwards AS ( SELECT SKU_GROUP, MIN(INWARD_DATE) AS FIRST_INWARD_DATE, MAX(INWARD_DATE) AS LATEST_INWARD_DATE, SUM(INWARD_QTY) AS TOTAL_INWARD_QTY, COUNT(DISTINCT INWARD_DATE) AS INWARD_EVENTS, CASE WHEN COUNT(DISTINCT INWARD_DATE)>1 THEN \'YES\' ELSE \'NO\' END AS REPEAT_ORDER FROM putaway_base GROUP BY SKU_GROUP ), mrp_map AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1 ) ) ) ) AS SKU_GROUP, MAX(MRP) AS MRP FROM snitch_db.maplemonk.snitch_final_inventory_wh2 GROUP BY 1 ), master_summary AS ( SELECT s.SKU_GROUP, s.CAPSULE, s.CATEGORY, img.IMAGE_URL, s.TOTAL_QTY, s.GROSS_SALES, s.TOTAL_DISCOUNT, s.ASP_GROSS, m.MRP, m.MRP * i.TOTAL_INWARD_QTY AS OPENING_GMV, m.MRP * inv.WH_INVENTORY AS WH_INVENTORY_VALUE, m.MRP * inv.STORE_INVENTORY AS STORE_INVENTORY_VALUE, m.MRP * (inv.WH_INVENTORY + inv.STORE_INVENTORY) AS TOTAL_INVENTORY_VALUE, m.MRP * s.TOTAL_QTY AS SOLD_MERCHANDISE_VALUE, inv.WH_INVENTORY, inv.STORE_INVENTORY, i.FIRST_INWARD_DATE, i.LATEST_INWARD_DATE, i.TOTAL_INWARD_QTY, i.INWARD_EVENTS, i.REPEAT_ORDER FROM sales_summary s LEFT JOIN images img ON s.SKU_GROUP=img.SKU_GROUP LEFT JOIN inventory inv ON s.SKU_GROUP=inv.SKU_GROUP LEFT JOIN inwards i ON s.SKU_GROUP=i.SKU_GROUP LEFT JOIN mrp_map m ON s.SKU_GROUP = m.SKU_GROUP ), business_metrics AS ( SELECT m.*, ROUND( (m.TOTAL_QTY / NULLIF(m.TOTAL_INWARD_QTY,0)) * 100, 2 ) AS STR_LIFETIME, DATEDIFF( DAY, m.FIRST_INWARD_DATE, CURRENT_DATE() ) + 1 AS DAYS_ACTIVE, ROUND( m.TOTAL_QTY / NULLIF( DATEDIFF( DAY, m.FIRST_INWARD_DATE, CURRENT_DATE() ) + 1, 0), 2) AS SALES_VELOCITY, ROUND( ((m.WH_INVENTORY + m.STORE_INVENTORY) / NULLIF(m.TOTAL_INWARD_QTY,0)) *100, 2) AS INVENTORY_REMAINING_PCT, ROUND( (m.WH_INVENTORY + m.STORE_INVENTORY) / NULLIF( m.TOTAL_QTY / NULLIF( DATEDIFF( DAY, m.FIRST_INWARD_DATE, CURRENT_DATE() ) + 1, 0), 0), 2) AS STOCK_COVER_DAYS, CASE WHEN m.REPEAT_ORDER=\'YES\' THEN 1 ELSE 0 END AS REPEAT_ORDER_FLAG FROM master_summary m ), online_customer_status AS ( SELECT c.COLLECTION AS CAPSULE, f.CUSTOMER_ID, MAX( CASE WHEN f.NEW_CUSTOMER_FLAG = \'New\' THEN 1 ELSE 0 END ) AS IS_NEW, MAX( CASE WHEN NVL(f.LOYALTY_CUSTOMER,\'NO\') = \'YES\' THEN 1 ELSE 0 END ) AS IS_LOYAL FROM SNITCH_DB.MAPLEMONK.fact_items_snitch f JOIN ( ( SELECT DISTINCT SKU, COLLECTION FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 UNION ALL SELECT DISTINCT skugroup as sku, CASE WHEN skugroup like \'%4MSFR%\' then \'PERFUMES\' else \'SHOES\' end as collection FROM snitch_db.maplemonk.uc_final_item_master where sku like \'%4MSFR%\' or sku like \'SH%\' ) ) c ON LOWER(f.SKU_GROUP) = LOWER(c.SKU) WHERE f.NEW_CUSTOMER_FLAG <> \'Yet to make completed order\' GROUP BY c.COLLECTION, f.CUSTOMER_ID ), online_customer_summary AS ( SELECT CAPSULE, COUNT(CASE WHEN IS_NEW = 1 THEN 1 END) AS ONLINE_NEW_USERS, COUNT(CASE WHEN IS_NEW = 0 THEN 1 END) AS ONLINE_REPEAT_USERS, COUNT(CASE WHEN IS_LOYAL = 1 THEN 1 END) AS ONLINE_LOYAL_USERS, COUNT(*) AS ONLINE_TOTAL_USERS FROM online_customer_status GROUP BY CAPSULE ), offline_customer_status AS ( SELECT c.COLLECTION AS CAPSULE, REGEXP_REPLACE(f.PHONE,\'[^0-9]\',\'\') AS PHONE, CASE WHEN a.PHONE_NO IS NULL THEN NULL WHEN CAST(a.FIRST_ORDER_DATE AS DATE) = CAST(f.ORDER_DATE AS DATE) THEN 1 ELSE 0 END AS IS_NEW FROM SNITCH_DB.MAPLEMONK.store_fact_items_offline f JOIN ( ( SELECT DISTINCT SKU, COLLECTION FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 UNION ALL SELECT DISTINCT skugroup as sku, CASE WHEN skugroup like \'%4MSFR%\' then \'PERFUMES\' else \'SHOES\' end as collection FROM snitch_db.maplemonk.uc_final_item_master where sku like \'%4MSFR%\' or sku like \'SH%\' ) ) c ON LOWER(f.SKU_GROUP)=LOWER(c.SKU) LEFT JOIN SNITCH_DB.MAPLEMONK.customer_acq_date_channel a ON CAST( RIGHT(REGEXP_REPLACE(f.PHONE,\'[^0-9]\',\'\'),10) AS VARCHAR ) = CAST( RIGHT(REGEXP_REPLACE(a.PHONE_NO,\'[^0-9]\',\'\'),10) AS VARCHAR ) WHERE f.PHONE IS NOT NULL ), offline_customer_summary AS ( SELECT CAPSULE, COUNT(DISTINCT CASE WHEN IS_NEW = 1 THEN PHONE END) AS OFFLINE_NEW_USERS, COUNT(DISTINCT CASE WHEN IS_NEW = 0 THEN PHONE END) AS OFFLINE_REPEAT_USERS, COUNT(DISTINCT CASE WHEN IS_NEW IS NOT NULL THEN PHONE END) AS OFFLINE_TOTAL_USERS FROM offline_customer_status GROUP BY CAPSULE ) SELECT bm.*, ocs.ONLINE_NEW_USERS, ocs.ONLINE_REPEAT_USERS, ocs.ONLINE_LOYAL_USERS, ocs.ONLINE_TOTAL_USERS, ROUND( ocs.ONLINE_REPEAT_USERS * 100.0 / NULLIF(ocs.ONLINE_TOTAL_USERS,0), 2) AS ONLINE_REPEAT_RATE, ROUND( ocs.ONLINE_NEW_USERS * 100.0 / NULLIF(ocs.ONLINE_TOTAL_USERS,0), 2) AS ONLINE_NEW_RATE, ROUND( ocs.ONLINE_LOYAL_USERS * 100.0 / NULLIF(ocs.ONLINE_TOTAL_USERS,0), 2) AS ONLINE_LOYALTY_RATE, ofs.OFFLINE_NEW_USERS, ofs.OFFLINE_REPEAT_USERS, ofs.OFFLINE_TOTAL_USERS, ROUND( ofs.OFFLINE_REPEAT_USERS * 100.0 / NULLIF(ofs.OFFLINE_TOTAL_USERS,0), 2) AS OFFLINE_REPEAT_RATE, ROUND( ofs.OFFLINE_NEW_USERS * 100.0 / NULLIF(ofs.OFFLINE_TOTAL_USERS,0), 2) AS OFFLINE_NEW_RATE, CASE WHEN bm.CAPSULE IN ( \'Embroided Shirts\', \'botanical THEME\', \'Street FC\', \'Street FC Plus\', \'GOLF POLO THEME\', \'PHOTO PRINT\', \'Try Less Denim\', \'PERFUMES\', \'SHOES\' ) THEN \'YES\' ELSE \'NO\' END AS FOCUS_CAPSULE, ROUND( (bm.TOTAL_DISCOUNT * 100.0) / NULLIF( bm.GROSS_SALES + bm.TOTAL_DISCOUNT, 0 ), 2 ) AS DISCOUNT_PCT, COALESCE(bm.WH_INVENTORY,0) + COALESCE(bm.STORE_INVENTORY,0) AS TOTAL_INVENTORY, ROUND( 100 - bm.STR_LIFETIME, 2) AS STR_REMAINING, CASE WHEN bm.DAYS_ACTIVE <= 30 THEN \'0-30 Days\' WHEN bm.DAYS_ACTIVE <= 60 THEN \'31-60 Days\' WHEN bm.DAYS_ACTIVE <= 90 THEN \'61-90 Days\' WHEN bm.DAYS_ACTIVE <= 120 THEN \'91-120 Days\' WHEN bm.DAYS_ACTIVE <= 180 THEN \'121-180 Days\' ELSE \'180+ Days\' END AS INVENTORY_AGE_BUCKET, CASE WHEN bm.STR_LIFETIME >= 80 THEN \'Excellent\' WHEN bm.STR_LIFETIME >= 60 THEN \'Good\' WHEN bm.STR_LIFETIME >= 40 THEN \'Average\' WHEN bm.STR_LIFETIME >= 20 THEN \'Slow\' ELSE \'Critical\' END AS STR_STATUS FROM business_metrics bm LEFT JOIN online_customer_summary ocs ON bm.CAPSULE = ocs.CAPSULE LEFT JOIN offline_customer_summary ofs ON bm.CAPSULE = ofs.CAPSULE ORDER BY bm.GROSS_SALES DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            